#include "assets.hpp"
#include <fstream>
#include <cstdio>
int main(int argc,char** argv){try{assetCheck(argc==3,"Expected WBFS and output folder");WiiAssets disc(std::filesystem::u8path(argv[1]));auto packed=disc.readFile("/AudioRes/SMR.szs");auto data=decodeYaz0(packed);std::printf("SMR: %zu compressed, %zu decoded, magic %08x\n",packed.size(),data.size(),be32(data.data()));std::ofstream raw(std::filesystem::u8path(argv[2])/"retail-audio.baa",std::ios::binary);raw.write(reinterpret_cast<const char*>(data.data()),data.size());assetCheck(bool(raw),"BAA save failed"); std::vector<std::vector<uint8_t>> candidates;if(be32(data.data())==0x41415f3c)candidates.push_back(std::move(data));else{Rarc archive(std::move(data));for(const auto& f:archive.files){std::printf("SMR entry %s %llu bytes\n",f.path.c_str(),static_cast<unsigned long long>(f.size));auto bytes=archive.readFile(f.path);if(bytes.size()>=4&&be32(bytes.data())==0x41415f3c)candidates.push_back(std::move(bytes));}}unsigned found=0;for(const auto& bytes:candidates)for(size_t i=4;i+12<=bytes.size();i+=4){auto tag=be32(bytes.data()+i);if(tag!=0x62737420&&tag!=0x6273746e)continue;size_t start=be32(bytes.data()+i+4),end=be32(bytes.data()+i+8);if(start>=end||end>bytes.size()||end-start<16)continue;if(be32(bytes.data()+start)!=(tag==0x62737420?0x42535420:0x4253544e))continue;auto path=std::filesystem::u8path(argv[2])/(tag==0x62737420?"retail-sound.bst":"retail-sound.bstn");std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()+start),end-start);assetCheck(bool(out),"Write failed");++found;std::printf("Verified table command at %zu extent %zu..%zu (%zu bytes)\n",i,start,end,end-start);}assetCheck(found==2,"Expected both retail sound tables");}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}}

